            const cardUrl = buildConvexBevelMap(260, 170, 26, 18);
            if (pillUrl && typeof pMap.setAttribute === 'function') pMap.setAttribute('href', pillUrl);
            if (cardUrl && typeof cMap.setAttribute === 'function') cMap.setAttribute('href', cardUrl);
