                twinkle: Math.random() * Math.PI * 2,
                speed: 0.004 + Math.random() * 0.01,
                gold: idx % 10 === 0,
                vx: (Math.random() - 0.5) * 0.12,
                vy: (Math.random() - 0.5) * 0.08,
